Here is the root cause:
The bug originates from commit a833a693a490 which incorrectly handled the subpool's used_hpages counter. When a global reservation fails after charging the subpool, the code decrements the subpool's reserve count but fails to decrement used_hpages for the globally requested pages. This causes used_hpages to leak upward over repeated failed allocations, eventually reaching the subpool's maximum and preventing any future allocations, even though no pages are actually consumed. The missing restoration of used_hpages in the error path of hugetlb_reserve_pages() is the root cause.

Here is the patch:

 long hugetlb_reserve_pages(struct inode *inode,
 		long from, long to,
 		struct vm_area_desc *desc,
 		vm_flags_t vm_flags)
 {
 	long chg = -1, add = -1, spool_resv, gbl_resv;
 	struct hstate *h = hstate_inode(inode);
 	struct hugepage_subpool *spool = subpool_inode(inode);
 	struct resv_map *resv_map;
 	struct hugetlb_cgroup *h_cg = NULL;
 	long gbl_reserve, regions_needed = 0;
 	int err;

 	/* This should never happen */
 	if (from > to) {
 		VM_WARN(1, "%s called with a negative range\n", __func__);
 		return -EINVAL;
 	}

 	/*
 	 * Only apply hugepage reservation if asked. At fault time, an
 	 * attempt will be made for VM_NORESERVE to allocate a page
 	 * without using reserves
 	 */
 	if (vm_flags & VM_NORESERVE)
 		return 0;

 	/*
 	 * Shared mappings base their reservation on the number of pages that
 	 * are already allocated on behalf of the file. Private mappings need
 	 * to reserve the full area even if read-only as mprotect() may be
 	 * called to make the mapping read-write. Assume !desc is a shm mapping
 	 */
 	if (!desc || desc->vm_flags & VM_MAYSHARE) {
 		/*
 		 * resv_map can not be NULL as hugetlb_reserve_pages is only
 		 * called for inodes for which resv_maps were created (see
 		 * hugetlbfs_get_inode).
 		 */
 		resv_map = inode_resv_map(inode);

 		chg = region_chg(resv_map, from, to, &regions_needed);
 	} else {
 		/* Private mapping. */
 		resv_map = resv_map_alloc();
 		if (!resv_map) {
 			err = -ENOMEM;
 			goto out_err;
 		}

 		chg = to - from;

 		set_vma_desc_resv_map(desc, resv_map);
 		set_vma_desc_resv_flags(desc, HPAGE_RESV_OWNER);
 	}

 	if (chg < 0) {
 		/* region_chg() above can return -ENOMEM */
 		err = (chg == -ENOMEM) ? -ENOMEM : -EINVAL;
 		goto out_err;
 	}

 	err = hugetlb_cgroup_charge_cgroup_rsvd(hstate_index(h),
 				chg * pages_per_huge_page(h), &h_cg);
 	if (err < 0)
 		goto out_err;

 	if (desc && !(desc->vm_flags & VM_MAYSHARE) && h_cg) {
 		/* For private mappings, the hugetlb_cgroup uncharge info hangs
 		 * of the resv_map.
 		 */
 		resv_map_set_hugetlb_cgroup_uncharge_info(resv_map, h_cg, h);
 	}

 	/*
 	 * There must be enough pages in the subpool for the mapping. If
 	 * the subpool has a minimum size, there may be some global
 	 * reservations already in place (gbl_reserve).
 	 */
 	gbl_reserve = hugepage_subpool_get_pages(spool, chg);
 	if (gbl_reserve < 0) {
 		err = gbl_reserve;
 		goto out_uncharge_cgroup;
 	}

 	/*
 	 * Check enough hugepages are available for the reservation.
 	 * Hand the pages back to the subpool if there are not
 	 */
 	err = hugetlb_acct_memory(h, gbl_reserve);
 	if (err < 0)
 		goto out_put_pages;

 	/*
 	 * Account for the reservations made. Shared mappings record regions
 	 * that have reservations as they are shared by multiple VMAs.
 	 * When the last VMA disappears, the region map says how much
 	 * the reservation was and the page cache tells how much of
 	 * the reservation was consumed. Private mappings are per-VMA and
 	 * only the consumed reservations are tracked. When the VMA
 	 * disappears, the original reservation is the VMA size and the
 	 * consumed reservations are stored in the map. Hence, nothing
 	 * else has to be done for private mappings here
 	 */
 	if (!desc || desc->vm_flags & VM_MAYSHARE) {
 		add = region_add(resv_map, from, to, regions_needed, h, h_cg);

 		if (unlikely(add < 0)) {
 			hugetlb_acct_memory(h, -gbl_reserve);
 			err = add;
 			goto out_put_pages;
 		} else if (unlikely(chg > add)) {
 			/*
 			 * pages in this range were added to the reserve
 			 * map between region_chg and region_add.  This
 			 * indicates a race with alloc_hugetlb_folio.  Adjust
 			 * the subpool and reserve counts modified above
 			 * based on the difference.
 			 */
 			long rsv_adjust;

 			/*
 			 * hugetlb_cgroup_uncharge_cgroup_rsvd() will put the
 			 * reference to h_cg->css. See comment below for detail.
 			 */
 			hugetlb_cgroup_uncharge_cgroup_rsvd(
 				hstate_index(h),
 				(chg - add) * pages_per_huge_page(h), h_cg);

 			rsv_adjust = hugepage_subpool_put_pages(spool,
 								chg - add);
 			hugetlb_acct_memory(h, -rsv_adjust);
 		} else if (h_cg) {
 			/*
 			 * The file_regions will hold their own reference to
 			 * h_cg->css. So we should release the reference held
 			 * via hugetlb_cgroup_charge_cgroup_rsvd() when we are
 			 * done.
 			 */
 			hugetlb_cgroup_put_rsvd_cgroup(h_cg);
 		}
 	}
 	return chg;

 out_put_pages:
 	spool_resv = chg - gbl_reserve;
 	if (spool_resv) {
 		/* put sub pool's reservation back, chg - gbl_reserve */
 		gbl_resv = hugepage_subpool_put_pages(spool, spool_resv);
 		/*
 		 * subpool's reserved pages can not be put back due to race,
 		 * return to hstate.
 		 */
 		hugetlb_acct_memory(h, -gbl_resv);
 	}
+	/* Restore used_hpages for pages that failed global reservation */
+	if (gbl_reserve && spool) {
+		unsigned long flags;
+
+		spin_lock_irqsave(&spool->lock, flags);
+		if (spool->max_hpages != -1)
+			spool->used_hpages -= gbl_reserve;
+		unlock_or_release_subpool(spool, flags);
+	}
 out_uncharge_cgroup:
 	hugetlb_cgroup_uncharge_cgroup_rsvd(hstate_index(h),
 					    chg * pages_per_huge_page(h), h_cg);
 out_err:
 	if (!desc || desc->vm_flags & VM_MAYSHARE)
 		/* Only call region_abort if the region_chg succeeded but the
 		 * region_add failed or didn't run.
 		 */
 		if (chg >= 0 && add < 0)
 			region_abort(resv_map, from, to, regions_needed);
 	if (desc && is_vma_desc_resv_set(desc, HPAGE_RESV_OWNER)) {
 		kref_put(&resv_map->refs, resv_map_release);
 		set_vma_desc_resv_map(desc, NULL);
 	}
 	return err;
 }



